def read_text(path):
    data = Path(path).read_bytes()
    if data[:2] == b"\x1f\x8b":
        data = gzip.decompress(data)
    return data.decode("utf-8-sig")


def lines_of(path):
    return [ln for ln in read_text(path).splitlines() if ln.strip()]


