    text = "\n".join(lines_of(path))
    return list(csv.DictReader(io.StringIO(text), **kw))


def to_utc(naive, zone, dst=None):
    first = naive.replace(tzinfo=zone, fold=0)
    second = naive.replace(tzinfo=zone, fold=1)
    chosen = first
    if first.utcoffset() != second.utcoffset() and dst is not None:
        chosen = first if dst else second
        if bool(first.dst()) != dst:
            chosen = second if dst is False or first.dst() else first
            chosen = first if bool(first.dst()) == dst else second
    return chosen.astimezone(UTC)


def parse_iso(text):
    text = text.strip()
    if text.endswith("Z") or text.endswith("z"):
        text = text[:-1] + "+00:00"
    dt = datetime.fromisoformat(text)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=UTC)
    return dt.astimezone(UTC)


def norm_dir(value):
    value = value.strip().upper()
    return "IN" if value in ("IN", "I", "CLOCK_IN", "K") else "OUT"


