        if "Badge" in cells and "Punch" in cells:
            header = cells
            continue
        if header is None:
            continue
        rec = dict(zip(header, cells))
        month, day, year = rec["Date"].split("/")
        match = re.match(r"(\d+):(\d+):(\d+)\s*([AaPp][Mm])?$", rec["Time"])
        hour, minute, second = int(match.group(1)), int(match.group(2)), int(match.group(3))
        mer = match.group(4)
        if mer:
            hour %= 12
            if mer.upper() == "PM":
                hour += 12
        naive = datetime(int(year), int(month), int(day), hour, minute, second)
        zone_name = rec.get("Zone", "").strip().upper()
        dst = True if zone_name.endswith("DT") else False if zone_name.endswith("ST") else None
        out.append((rec["Record"], rec["Badge"], norm_dir(rec["Punch"]), to_utc(naive, zone, dst)))
    return out


def from_ms(value):
    return EPOCH + timedelta(milliseconds=int(value))


