            schema = int(obj["schema"])
            continue
        if obj.get("heartbeat"):
            continue
        if schema == 2:
            instant = from_ms(obj["epoch_ms"])
            out.append((str(obj["punch_id"]), obj["employee"], norm_dir(obj["direction"]), instant))
        else:
            if "ts_ms" in obj:
                instant = from_ms(obj["ts_ms"])
            else:
                instant = EPOCH + timedelta(seconds=int(obj["ts"]))
            out.append((str(obj["id"]), obj["emp"], norm_dir(obj["dir"]), instant))
    return out


def parse_offset(path, zone):
    out = []
    for rec in read_csv_rows(path, delimiter=";"):
        out.append((rec["punch_id"], rec["employee"], norm_dir(rec["event"]), parse_iso(rec["timestamp"])))
    return out


def standard_offset(zone, naive):
    probe = naive.replace(tzinfo=zone)
    return probe.utcoffset() - (probe.dst() or timedelta(0))


def parse_legacy(path, zone):
