        if kind == "H":
            field = line[13:18].strip()
            if field:
                sign = -1 if field[0] == "-" else 1
                offset = sign * timedelta(hours=int(field[1:3]), minutes=int(field[3:5]))
            else:
                offset = None
        elif kind == "D":
            punch_id = line[1:9]
            badge = "E" + line[9:15].strip()
            direction = "IN" if line[15] == "I" else "OUT"
            naive = datetime.strptime(line[16:30], "%Y%m%d%H%M%S")
            use = offset if offset is not None else standard_offset(zone, naive)
            out.append((punch_id, badge, direction, (naive - use).replace(tzinfo=UTC)))
    return out


def parse_de(path, zone):
