        rec = {k.strip(): (v or "").strip() for k, v in rec.items() if k}
        day, month, year = rec["Datum"].split(".")
        hour, minute = rec["Uhrzeit"].split(":")[:2]
        naive = datetime(int(year), int(month), int(day), int(hour), int(minute))
        dst = rec["Zeitzone"].upper() == "MESZ"
        out.append((rec["Nr"], rec["Ausweis"], norm_dir(rec["Buchung"]), to_utc(naive, zone, dst)))
    return out


def parse_local_csv(path, zone):
