        naive = datetime.strptime(rec["local_time"].strip(), "%Y-%m-%d %H:%M:%S")
        out.append((rec["punch_ref"].strip(), rec["employee_id"].strip(), norm_dir(rec["direction"]),
                    to_utc(naive, zone, True)))
    return out


def parse_local_jsonl(path, zone):
    out = []
    for line in lines_of(path):
        obj = json.loads(line)
        punch = obj.get("punch")
        if not isinstance(punch, dict):
            continue
        naive = datetime.strptime(punch["at"].strip(), "%Y-%m-%d %H:%M:%S")
        out.append((str(punch["id"]).strip(), punch["badge"], norm_dir(punch["type"]),
                    to_utc(naive, zone, True)))
    return out


