def night_minutes(start, end, zone):
    total = 0
    cursor = start
    while cursor < end:
        step = min(timedelta(minutes=6), end - cursor)
        hour = cursor.astimezone(zone).hour
        if hour >= 22 or hour < 6:
            total += int(step.total_seconds() // 60)
        cursor += step
    return total


