                    exc["duplicates_dropped"] += 1
                continue
            entry = (at, 0, site, punch_id, direction, rounded)
            kept.append(entry)
            last = entry

        shifts = []
        pending = None

        def workday(entry):
            return entry[5].astimezone(home).date()

        for entry in kept:
            if entry[4] == "IN":
                if pending is not None and in_period(workday(pending)):
                    exc["open_shifts"] += 1
                pending = entry
            else:
                if pending is not None and entry[5] - pending[5] <= timedelta(hours=16):
                    shifts.append((pending, entry))
                    pending = None
                else:
                    if pending is not None and in_period(workday(pending)):
                        exc["open_shifts"] += 1
                    pending = None
                    if in_period(workday(entry)):
                        exc["orphan_outs"] += 1
        if pending is not None and in_period(workday(pending)):
            exc["open_shifts"] += 1

