                continue
            worked = max(0, int((out[5] - inn[5]).total_seconds() // 60))
            paid = worked - 30 if worked > 360 else worked
            night = min(night_minutes(inn[5], out[5], sites[inn[2]][0]), paid)
            rows.append({"in": inn[5], "wd": wd, "paid": paid, "night": night})
        rows.sort(key=lambda r: r["in"])

        daily_used = {}
        for row in rows:
            before = daily_used.get(row["wd"], 0)
            after = before + row["paid"]
            daily_used[row["wd"]] = after
            row["daily_ot"] = max(0, after - 480) - max(0, before - 480)
        week_used = {}
        for row in rows:
            week = row["wd"] - timedelta(days=row["wd"].weekday())
            counted = row["paid"] - row["daily_ot"]
            before = week_used.get(week, 0)
            after = before + counted
            week_used[week] = after
            row["ot"] = row["daily_ot"] + max(0, after - 2400) - max(0, before - 2400)

        gross = Fraction(0)
        data = result[emp]
        for row in rows:
            rate_list = rates.get(emp, [])
            rate = Fraction(0)
            for eff, value in rate_list:
                if eff <= row["wd"]:
                    rate = value
            regular = row["paid"] - row["ot"]
            gross += rate * (regular + Fraction(3, 2) * row["ot"]) / 60 + rate * Fraction(15, 100) * row["night"] / 60
            data["shifts"] += 1
            data["paid_minutes"] += row["paid"]
            data["overtime_minutes"] += row["ot"]
            data["night_minutes"] += row["night"]
        data["gross"] = int((gross * 100 + Fraction(1, 2)) // 1)

    totals = {"shifts": 0, "paid_minutes": 0, "overtime_minutes": 0, "night_minutes": 0, "gross": 0}
    for emp, data in result.items():
        for field in totals:
            totals[field] += data[field]
        data["gross"] = "%d.%02d" % divmod(data["gross"], 100)
    totals["gross"] = "%d.%02d" % divmod(totals["gross"], 100)
    summary = {"period": {"start": period["start"], "end": period["end"]},
               "employees": result, "exceptions": exc, "totals": totals}
    output_file.parent.mkdir(parents=True, exist_ok=True)
    output_file.write_text(json.dumps(summary, indent=1))


